generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryLabel 
       (SUM(xsd:decimal(?totalCashFlow)) AS ?totalCashFlow) 
       (AVG(xsd:decimal(?avgScenarioChange)) AS ?avgScenarioChange) 
       (SUM(xsd:decimal(?totalAllocationPct)) AS ?totalAllocationPct) 
       (SUM(xsd:decimal(?totalSectorInvestment)) AS ?totalSectorInvestment) 
       (SUM(xsd:decimal(?totalHoldingValue)) AS ?totalHoldingValue)
WHERE {
  # Map each investor to a single category (via any of its holdings)
  {
    SELECT ?investorId (SAMPLE(?cat) AS ?category) WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:investorId ?investorId ;
          wm:hasCategory ?cat .
    } GROUP BY ?investorId
  }

  # Cash flow per investor
  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?totalCashFlow) WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amount .
    } GROUP BY ?investorId
  }

  # Scenario change per investor (new - current allocation)
  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPct)) AS ?avgScenarioChange) WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:newAllocationPct ?newAllocationPct ;
          wm:currentAllocationPct ?currentAllocationPct .
    } GROUP BY ?investorId
  }

  # Sector allocation per investor
  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?allocationPct)) AS ?totalAllocationPct) (SUM(xsd:decimal(?totalInvestment)) AS ?totalSectorInvestment) WHERE {
      ?sa a wm:SectorAllocation ;
          wm:investorId ?investorId ;
          wm:allocationPct ?allocationPct ;
          wm:totalInvestment ?totalInvestment .
    } GROUP BY ?investorId
  }

  # Portfolio holding value per investor
  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?currentValue)) AS ?totalHoldingValue) WHERE {
      ?ph2 a wm:PortfolioHolding ;
           wm:investorId ?investorId ;
           wm:currentValue ?currentValue .
    } GROUP BY ?investorId
  }

  BIND(?category AS ?cat)
  OPTIONAL { ?cat rdfs:label ?categoryLabel . }
}
GROUP BY ?categoryLabel

